Oh dear. Oh dear oh dear. A configuration management CLI. Do you have ANY idea how many ways this could go wrong? The categorical imperative demands we consider EVERY edge case!

```go
package config_test

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)

func TestConfigCLI(t *testing.T) {
	// But wait - what if the test itself is flawed? 
	// No, focus Chidi. Table-driven tests. Kant would approve of the universalizability.

	tests := []struct {
		name       string
		args       []string
		wantCode   int
		wantStdout string
		wantStderr string
	}{
		// Happy paths - though is any path truly happy?
		{"init creates config", []string{"init"}, 0, "Config initialized", ""},
		{"get existing key", []string{"get", "database.host"}, 0, "localhost", ""},
		{"set value", []string{"set", "port", "8080"}, 0, "", ""},
		{"list keys", []string{"list"}, 0, "database.host\nport", ""},
		{"validate good config", []string{"validate"}, 0, "Valid", ""},

		// The moral failures - exit code 1
		{"get missing key", []string{"get", "nonexistent"}, 1, "", "key not found"},
		{"delete missing key", []string{"delete", "ghost"}, 1, "", "key not found"},
		{"validate bad yaml", []string{"validate"}, 1, "", "invalid YAML"},

		// Usage errors - exit code 2 (the purgatory of exit codes)
		{"no subcommand", []string{}, 2, "", "Usage:"},
		{"unknown command", []string{"explode"}, 2, "", "unknown command"},
		{"get no key", []string{"get"}, 2, "", "requires key argument"},
		{"set missing value", []string{"set", "key"}, 2, "", "requires key and value"},
		{"invalid format flag", []string{"--format", "xml", "list"}, 2, "", "invalid format"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// Each test in isolation - Rawlsian veil of ignorance!
			tmpDir := t.TempDir()
			// ... execute and verify
		})
	}
}

func TestFileSystemOperations(t *testing.T) {
	// Oh no. File permissions. What if we're on a read-only filesystem?
	// What if there's a race condition? WHAT IF THERE'S A RACE CONDITION?!

	t.Run("creates parent directories", func(t *testing.T) {
		tmpDir := t.TempDir()
		configPath := filepath.Join(tmpDir, "deep", "nested", "config.yaml")
		// init should create parents - but IS it ethical to create directories without consent?
	})

	t.Run("permission denied", func(t *testing.T) {
		if os.Getuid() == 0 {
			t.Skip("cannot test permissions as root") // Root users: beyond moral judgment
		}
		tmpDir := t.TempDir()
		os.Chmod(tmpDir, 0444)
		defer os.Chmod(tmpDir, 0755)
		// Should exit 1 with helpful error, not panic!
	})

	t.Run("concurrent access", func(t *testing.T) {
		// The trolley problem of config files - do we lock? Do we fail?
		// I've written 47 variations of this test and I'm still not certain.
	})
}

func TestOutputFormatting(t *testing.T) {
	// Data to stdout, errors to stderr - a Kantian duty!
	formats := []string{"json", "yaml", "text"}
	for _, fmt := range formats {
